#!/bin/bash
# Uninstall script for Homebrew
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Homebrew..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Homebrew if running..."
pkill -f "Homebrew" 2>/dev/null || true

# Remove /Applications/Homebrew.app
echo "Removing /Applications/Homebrew.app..."
if [ -d "/Applications/Homebrew.app" ]; then
    rm -rf "/Applications/Homebrew.app" 2>/dev/null || true
elif [ -f "/Applications/Homebrew.app" ]; then
    rm -f "/Applications/Homebrew.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/sh.brew.app
echo "Removing $HOME/Library/Application Support/sh.brew.app..."
if [ -d "$HOME/Library/Application Support/sh.brew.app" ]; then
    rm -rf "$HOME/Library/Application Support/sh.brew.app" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/sh.brew.app" ]; then
    rm -f "$HOME/Library/Application Support/sh.brew.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/sh.brew.app
echo "Removing $HOME/Library/Caches/sh.brew.app..."
if [ -d "$HOME/Library/Caches/sh.brew.app" ]; then
    rm -rf "$HOME/Library/Caches/sh.brew.app" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/sh.brew.app" ]; then
