fi

# Remove $HOME/Library/Preferences/sh.brew.app.plist
echo "Removing $HOME/Library/Preferences/sh.brew.app.plist..."
if [ -d "$HOME/Library/Preferences/sh.brew.app.plist" ]; then
    rm -rf "$HOME/Library/Preferences/sh.brew.app.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/sh.brew.app.plist" ]; then
    rm -f "$HOME/Library/Preferences/sh.brew.app.plist" 2>/dev/null || true
